import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  createOrder,
  getCustomerOrders,
  getOrderById,
  getAllOrders,
  adminGetOrderById,
  updateOrderStatus,
} from '@/services/orderService';
import type { CreateOrderRequest, Order } from '@/types/order';

export const useOrders = () => {
  const queryClient = useQueryClient();

  const {
    data: customerOrders,
    isLoading: isLoadingCustomerOrders,
    isError: isErrorCustomerOrders,
    error: customerOrdersError,
  } = useQuery<Order[]>({
    queryKey: ['customerOrders'],
    queryFn: getCustomerOrders,
  });

  const {
    data: allOrders,
    isLoading: isLoadingAllOrders,
    isError: isErrorAllOrders,
    error: allOrdersError,
  } = useQuery<Order[]>({
    queryKey: ['allOrders'],
    queryFn: getAllOrders,
  });

  const createOrderMutation = useMutation<Order, Error, CreateOrderRequest>({
    mutationFn: createOrder,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customerOrders'] });
      queryClient.invalidateQueries({ queryKey: ['allOrders'] });
    },
  });

  const getOrderByIdQuery = (orderId: string) =>
    useQuery<Order, Error>({
      queryKey: ['order', orderId],
      queryFn: () => getOrderById(orderId),
      enabled: !!orderId,
    });

  const adminGetOrderByIdQuery = (orderId: string) =>
    useQuery<Order, Error>({
      queryKey: ['adminOrder', orderId],
      queryFn: () => adminGetOrderById(orderId),
      enabled: !!orderId,
    });

  const updateOrderStatusMutation = useMutation<Order, Error, string>({
    mutationFn: updateOrderStatus,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['allOrders'] });
      queryClient.invalidateQueries({ queryKey: ['adminOrder'] });
    },
  });

  return {
    customerOrders,
    isLoadingCustomerOrders,
    isErrorCustomerOrders,
    customerOrdersError,
    allOrders,
    isLoadingAllOrders,
    isErrorAllOrders,
    allOrdersError,
    createOrder: createOrderMutation.mutate,
    isCreatingOrder: createOrderMutation.isPending,
    createOrderError: createOrderMutation.error,
    createdOrder: createOrderMutation.data,
    getOrderByIdQuery,
    adminGetOrderByIdQuery,
    updateOrderStatus: updateOrderStatusMutation.mutate,
    isUpdatingOrderStatus: updateOrderStatusMutation.isPending,
    updateOrderStatusError: updateOrderStatusMutation.error,
  };
};

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import * as z from "zod";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { useCustomer } from "@/hooks/useCustomer";
import { useEffect } from "react";

const profileFormSchema = z.object({
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  email: z.string().email("Invalid email address"),
  phone: z.string().min(10, "Phone number must be at least 10 digits").optional().or(z.literal('')),
  address: z.string().optional().or(z.literal('')),
});

type ProfileFormValues = z.infer<typeof profileFormSchema>;

export default function UserProfileForm() {
  const { customer, isLoading, updateCustomerProfile } = useCustomer();

  const form = useForm<ProfileFormValues>({
    resolver: zodResolver(profileFormSchema),
    defaultValues: {
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      address: "",
    },
  });

  useEffect(() => {
    if (customer) {
      form.reset({
        firstName: customer.firstName ?? "",
        lastName: customer.lastName ?? "",
        email: customer.email ?? "",
        phone: customer.phone ?? "",
        address: customer.address ?? "",
      });
    }
  }, [customer, form]);

  async function onSubmit(values: ProfileFormValues) {
    try {
      await updateCustomerProfile({
        ...customer,
        firstName: values.firstName,
        lastName: values.lastName,
        email: values.email,
        phone: values.phone,
        address: values.address,
      });
      toast.success("Profile updated successfully!");
    } catch (error) {
      toast.error("Failed to update profile.");
      console.error("Failed to update profile:", error);
    }
  }

  if (isLoading) {
    return <div>Loading profile...</div>;
  }

  return (
    <div className="p-6 bg-white rounded-xl shadow-md border border-gray-100">
      <h2 className="text-2xl font-semibold mb-4">Your Profile</h2>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          <FormField
            control={form.control}
            name="firstName"
            render={({ field }) => (
              <FormItem>
                <FormLabel>First Name</FormLabel>
                <FormControl>
                  <Input placeholder="First Name" {...field} data-testid="profile-firstName" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="lastName"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Last Name</FormLabel>
                <FormControl>
                  <Input placeholder="Last Name" {...field} data-testid="profile-lastName" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="email"
