                    <p className="text-sm text-gray-600">{formatCurrency(item.unitPrice)} each</p>
                  </div>
                </div>
                <div className="flex items-center space-x-4">
                  <div className="flex items-center">
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => setItemQuantity(item.id, item.quantity - 1, item.variantKey)}
                      disabled={item.quantity <= 1}
                      data-testid={`decrease-quantity-${item.id}`}
                    >
                      <MinusCircle className="h-4 w-4" />
                    </Button>
                    <Input
                      type="number"
                      value={item.quantity}
                      onChange={(e) => {
                        const newQty = parseInt(e.target.value);
                        if (!isNaN(newQty) && newQty > 0) {
                          setItemQuantity(item.id, newQty, item.variantKey);
                        }
                      }}
                      className="w-16 text-center mx-2"
                      min="1"
                      data-testid={`item-quantity-${item.id}`}
                    />
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => setItemQuantity(item.id, item.quantity + 1, item.variantKey)}
                      data-testid={`increase-quantity-${item.id}`}
                    >
                      <PlusCircle className="h-4 w-4" />
                    </Button>
                  </div>
                  <p className="font-medium w-24 text-right">{formatCurrency(item.unitPrice * item.quantity)}</p>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => removeItem(item.id, item.variantKey)}
                    data-testid={`remove-item-${item.id}`}
                  >
                    <Trash2 className="h-4 w-4 text-red-500" />
                  </Button>
                </div>
              </div>
            ))}

            <Separator className="my-4" />

            <div className="space-y-2">
              <div className="flex justify-between font-medium">
                <span>Subtotal:</span>
                <span>{formatCurrency(totals.subtotal)}</span>
              </div>
              {totals.adjustments.map((adj) => (
                <div key={adj.id} className="flex justify-between text-sm text-gray-700">
                  <span>{adj.label}:</span>
                  <span>{formatCurrency(adj.amount)}</span>
                </div>
              ))}
              <div className="flex justify-between text-lg font-bold pt-2">
                <span>Total:</span>
                <span>{formatCurrency(totals.total)}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { format } from 'date-fns';
import { CalendarIcon } from 'lucide-react';
import { toast } from 'sonner';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Textarea } from '@/components/ui/textarea';
import { useReservations } from '@/hooks/useReservations';
import type { ReservationRequest } from '@/types/reservation';

const reservationFormSchema = z.object({
  customerName: z.string().min(1, 'Name is required'),
  customerPhone: z.string().min(1, 'Phone number is required'),
  customerEmail: z.string().email('Invalid email address').min(1, 'Email is required'),
  reservationDate: z.date({
    required_error: 'A reservation date is required.',
  }),
  reservationTime: z.string().min(1, 'Time is required'),
  numberOfGuests: z.coerce.number().min(1, 'At least 1 guest is required'),
  specialRequests: z.string().optional(),
});

type ReservationFormValues = z.infer<typeof reservationFormSchema>;

export default function ReservationForm() {
  const { createReservation, isPending } = useReservations();
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  const form = useForm<ReservationFormValues>({
    resolver: zodResolver(reservationFormSchema),
    defaultValues: {
      customerName: '',
      customerPhone: '',
      customerEmail: '',
      reservationTime: '',
      numberOfGuests: 1,
      specialRequests: '',
    },
  });

  const onSubmit = (values: ReservationFormValues) => {
    const request: ReservationRequest = {
      customerName: values.customerName,
      customerPhone: values.customerPhone,
      customerEmail: values.customerEmail,
      reservationDate: format(values.reservationDate, 'yyyy-MM-dd'),
      reservationTime: values.reservationTime,
      numberOfGuests: values.numberOfGuests,
      specialRequests: values.specialRequests,
    };

    createReservation(request, {
      onSuccess: () => {
        toast.success('Reservation created successfully!');
        form.reset();
        setSelectedDate(undefined);
      },
      onError: (error) => {
        toast.error('Failed to create reservation.', {
          description: error.message || 'Please try again.',
        });
      },
    });
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6" data-testid="reservation-form">
        <FormField
          control={form.control}
          name="customerName"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Name</FormLabel>
              <FormControl>
                <Input placeholder="Your Name" {...field} data-testid="reservation-customerName" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="customerPhone"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Phone Number</FormLabel>
              <FormControl>
                <Input placeholder="Your Phone Number" {...field} data-testid="reservation-customerPhone" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="customerEmail"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Email</FormLabel>
              <FormControl>
                <Input placeholder="Your Email" {...field} data-testid="reservation-customerEmail" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="reservationDate"
          render={({ field }) => (
            <FormItem className="flex flex-col">
              <FormLabel>Reservation Date</FormLabel>
              <Popover>
                <PopoverTrigger asChild>
                  <FormControl>
                    <Button
                      variant={'outline'}
                      className={cn(
                        'w-full pl-3 text-left font-normal',
                        !field.value && 'text-muted-foreground'
                      )}
                      data-testid="reservation-reservationDate-trigger"
                    >
                      {field.value ? (
                        format(field.value, 'PPP')
                      ) : (
                        <span>Pick a date</span>
                      )}
                      <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                    </Button>
                  </FormControl>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={field.value}
                    onSelect={(date) => {
                      field.onChange(date);
                      setSelectedDate(date);
                    }}
                    disabled={(date) => date < new Date() || date < new Date('1900-01-01')}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="reservationTime"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Reservation Time</FormLabel>
              <FormControl>
                <Input type="time" {...field} data-testid="reservation-reservationTime" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="numberOfGuests"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Number of Guests</FormLabel>
              <FormControl>
                <Input type="number" {...field} data-testid="reservation-numberOfGuests" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="specialRequests"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Special Requests</FormLabel>
              <FormControl>
                <Textarea placeholder="Any special requests?" {...field} data-testid="reservation-specialRequests" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <Button type="submit" className="w-full bg-[#D4AF37] hover:bg-[#C2A032] text-white font-semibold rounded-full px-8 py-3 transition-all duration-200" disabled={isPending} data-testid="reservation-submit-cta">
          {isPending ? 'Submitting...' : 'Make Reservation'}
        </Button>
      </form>
    </Form>
  );
}

"use client";

import { useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { useCart } from '@/cart/CartContext';
import { useAuth } from '@/hooks/useAuth';
import { useOrders } from '@/hooks/useOrders';
import { CreateOrderRequest } from '@/types/order';
import { toast } from 'sonner';
import { CheckoutStep } from '@/cart/types';

interface PaymentStepProps {
  onNext: (step: CheckoutStep) => void;
  deliveryAddress: string;
  contactPhone: string;
}

export default function PaymentStep({ onNext, deliveryAddress, contactPhone }: PaymentStepProps) {
  const { totals, cartItems, clearCart } = useCart();
  const { user } = useAuth();
  const { createOrder, isCreatingOrder, createOrderError, createdOrder } = useOrders();

  const handlePlaceOrder = () => {
    if (!user?.id) {
      toast.error("User not authenticated. Please log in.");
      return;
    }

    if (!deliveryAddress || !contactPhone) {
      toast.error("Delivery address and contact phone are required.");
      return;
    }

    if (!cartItems || cartItems.length === 0) {
      toast.error("Your cart is empty. Please add items before placing an order.");
      return;
    }

    const orderItems = cartItems.map(item => ({
      menuItemId: item.id as string,
      quantity: item.quantity,
    }));

    const orderRequest: CreateOrderRequest = {
      customerId: user.id,
      deliveryAddress,
      contactPhone,
      orderItems,
    };

    createOrder(orderRequest);
  };

  useEffect(() => {
    if (createdOrder) {
      if (createdOrder.paymentLink) {
        toast.success("Order placed successfully! Redirecting to payment gateway...");
        clearCart();
        window.location.href = createdOrder.paymentLink;
      } else {
        toast.success("Order placed successfully, awaiting payment confirmation.");
        clearCart();
        onNext(CheckoutStep.ORDER_CONFIRMATION); // Assuming there's a confirmation step
      }
    }
  }, [createdOrder, clearCart, onNext]);

  useEffect(() => {
    if (createOrderError) {
      toast.error(`Failed to place order: ${createOrderError.message}`);
    }
  }, [createOrderError]);

  const formattedTotal = totals.total.toLocaleString('en-IN', { style: 'currency', currency: 'INR' });

  return (
    <Card className="w-full max-w-2xl mx-auto" data-testid="payment-step-card">
      <CardHeader>
        <CardTitle className="text-2xl md:text-3xl font-semibold">Confirm Order & Pay</CardTitle>
        <CardDescription className="text-gray-700 leading-relaxed">
          Review your order and proceed to payment.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex justify-between items-center text-lg font-medium">
          <span>Total Amount:</span>
          <span className="text-[#D4AF37]">{formattedTotal}</span>
        </div>
        <div className="text-sm text-gray-600">
          Please click "Place Order & Pay" to finalize your order and be redirected to our secure payment gateway.
        </div>
      </CardContent>
      <CardFooter>
        <Button
          onClick={handlePlaceOrder}
          disabled={isCreatingOrder}
          className="bg-[#D4AF37] hover:bg-[#b89a30] text-white font-semibold rounded-full px-8 py-3 transition-all duration-200 w-full"
          data-testid="place-order-pay-cta"
        >
          {isCreatingOrder ? 'Processing...' : 'Place Order & Pay'}
        </Button>
      </CardFooter>
    </Card>
  );
}

