import { useQueryClient, useQuery } from '@tanstack/react-query';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { MoreHorizontal } from 'lucide-react';
import { deleteReservation, getAllReservations, updateReservation } from '@/services/reservationService';
import { Reservation, ReservationStatus } from '@/types/reservation';
import { toast } from 'sonner';

export default function ReservationsTable() {
  const queryClient = useQueryClient();
  const { data: reservations, isLoading, isError, error } = useQuery<Reservation[]>({
    queryKey: ['reservations'],
    queryFn: getAllReservations,
  });

  const handleDelete = async (id: string) => {
    try {
      await deleteReservation(id);
      queryClient.invalidateQueries({ queryKey: ['reservations'] });
      toast.success('Reservation deleted successfully.');
    } catch (err) {
      toast.error('Failed to delete reservation.');
      console.error('Failed to delete reservation:', err);
    }
  };

  const handleUpdateStatus = async (id: string, status: ReservationStatus) => {
    try {
      const reservationToUpdate = reservations?.find(r => r.id === id);
      if (!reservationToUpdate) {
        toast.error('Reservation not found.');
        return;
      }
      await updateReservation(id, { ...reservationToUpdate, status });
      queryClient.invalidateQueries({ queryKey: ['reservations'] });
      toast.success('Reservation status updated successfully.');
    } catch (err) {
      toast.error('Failed to update reservation status.');
      console.error('Failed to update reservation status:', err);
    }
  };

  if (isLoading) {
    return <div>Loading reservations...</div>;
  }

  if (isError) {
    return <div>Error loading reservations: {error?.message}</div>;
  }

  return (
    <div className="rounded-md border">
      <Table data-testid="reservations-table">
        <TableHeader>
          <TableRow>
            <TableHead>Customer Name</TableHead>
            <TableHead>Date</TableHead>
            <TableHead>Time</TableHead>
            <TableHead>Guests</TableHead>
            <TableHead>Status</TableHead>
            <TableHead>Special Requests</TableHead>
            <TableHead className="text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {reservations?.length === 0 ? (
            <TableRow>
              <TableCell colSpan={7} className="h-24 text-center">
                No reservations found.
              </TableCell>
            </TableRow>
          ) : (
            reservations?.map((reservation) => (
              <TableRow key={reservation.id} data-testid={`reservation-row-${reservation.id}`}>
                <TableCell>{reservation.customerName}</TableCell>
                <TableCell>
                  {reservation.reservationDate
                    ? new Date(reservation.reservationDate).toLocaleDateString('en-IN')
                    : 'N/A'}
                </TableCell>
                <TableCell>{reservation.reservationTime}</TableCell>
                <TableCell>{reservation.partySize}</TableCell>
                <TableCell>{reservation.status}</TableCell>
                <TableCell>{reservation.specialRequests ?? 'N/A'}</TableCell>
                <TableCell className="text-right">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" className="h-8 w-8 p-0" data-testid={`reservation-actions-${reservation.id}`}>
                        <span className="sr-only">Open menu</span>
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => handleUpdateStatus(reservation.id, 'CONFIRMED')} data-testid={`reservation-status-confirmed-${reservation.id}`}>
                        Mark Confirmed
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => handleUpdateStatus(reservation.id, 'CANCELLED')} data-testid={`reservation-status-cancelled-${reservation.id}`}>
                        Mark Cancelled
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => handleUpdateStatus(reservation.id, 'COMPLETED')} data-testid={`reservation-status-completed-${reservation.id}`}>
                        Mark Completed
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => handleDelete(reservation.id)} data-testid={`reservation-delete-${reservation.id}`}>
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );
}

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { MenuItemDto } from '@/types/menu';
import { useMenu } from '@/hooks/useMenu';
import { toast } from 'sonner';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { createMenuItem, updateMenuItem } from '@/services/menuService';

const formSchema = z.object({
  name: z.string().min(2, { message: 'Name must be at least 2 characters.' }),
  description: z.string().optional(),
  price: z.coerce.number().min(0.01, { message: 'Price must be a positive number.' }),
  imageUrl: z.string().url({ message: 'Invalid URL for image.' }).optional().or(z.literal('')),
  vegetarian: z.boolean().default(false),
  spicy: z.boolean().default(false),
  categoryId: z.string().min(1, { message: 'Category is required.' }),
});

type MenuItemFormValues = z.infer<typeof formSchema>;

interface MenuItemFormProps {
  initialData?: MenuItemDto;
  onSuccess?: () => void;
}

export default function MenuItemForm({ initialData, onSuccess }: MenuItemFormProps) {
  const queryClient = useQueryClient();
  const { menuCategories, isLoading: isLoadingCategories } = useMenu();

  const form = useForm<MenuItemFormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: initialData?.name ?? '',
      description: initialData?.description ?? '',
      price: initialData?.price ?? 0,
      imageUrl: initialData?.imageUrl ?? '',
      vegetarian: initialData?.vegetarian ?? false,
      spicy: initialData?.spicy ?? false,
      categoryId: initialData?.categoryId ?? '',
    },
  });

  useEffect(() => {
    if (initialData) {
      form.reset({
        name: initialData.name ?? '',
        description: initialData.description ?? '',
        price: initialData.price ?? 0,
        imageUrl: initialData.imageUrl ?? '',
        vegetarian: initialData.vegetarian ?? false,
        spicy: initialData.spicy ?? false,
        categoryId: initialData.categoryId ?? '',
      });
    }
  }, [initialData, form]);

  const createMutation = useMutation({
    mutationFn: createMenuItem,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['menuItems'] });
      queryClient.invalidateQueries({ queryKey: ['menuCategories'] });
      toast.success('Menu item created successfully.');
      onSuccess?.();
    },
    onError: (error) => {
      toast.error(`Failed to create menu item: ${error.message}`);
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: MenuItemDto }) => updateMenuItem(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['menuItems'] });
      queryClient.invalidateQueries({ queryKey: ['menuCategories'] });
      toast.success('Menu item updated successfully.');
      onSuccess?.();
    },
    onError: (error) => {
      toast.error(`Failed to update menu item: ${error.message}`);
    },
  });

  const onSubmit = (values: MenuItemFormValues) => {
    const menuItemDto: MenuItemDto = {
      id: initialData?.id ?? null,
      name: values.name,
      description: values.description,
      price: values.price,
      imageUrl: values.imageUrl,
      vegetarian: values.vegetarian,
      spicy: values.spicy,
      categoryId: values.categoryId,
      categoryName: menuCategories.find(cat => cat.id === values.categoryId)?.name ?? null,
    };

    if (initialData?.id) {
      updateMutation.mutate({ id: initialData.id, data: menuItemDto });
    } else {
      createMutation.mutate(menuItemDto);
    }
  };

  const isSubmitting = createMutation.isPending || updateMutation.isPending;

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4" data-testid="menu-item-form">
        <FormField
          control={form.control}
          name="name"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Name</FormLabel>
              <FormControl>
                <Input placeholder="Menu Item Name" {...field} data-testid="menu-item-name" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="description"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Description</FormLabel>
              <FormControl>
                <Textarea placeholder="Description" {...field} data-testid="menu-item-description" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="price"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Price</FormLabel>
              <FormControl>
                <Input type="number" step="0.01" placeholder="0.00" {...field} onChange={e => field.onChange(parseFloat(e.target.value))} data-testid="menu-item-price" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="imageUrl"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Image URL</FormLabel>
              <FormControl>
                <Input placeholder="https://example.com/image.jpg" {...field} data-testid="menu-item-image-url" />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="categoryId"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Category</FormLabel>
              <Select onValueChange={field.onChange} defaultValue={field.value}>
                <FormControl>
                  <SelectTrigger data-testid="menu-item-category-select">
                    <SelectValue placeholder="Select a category" />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {isLoadingCategories ? (
                    <SelectItem value="loading" disabled>Loading categories...</SelectItem>
                  ) : (
                    menuCategories
                      .filter(category => category.id !== 'all') // Exclude 'All' category from form
                      .map((category) => (
                        <SelectItem key={category.id} value={category.id} data-testid={`menu-item-category-option-${category.id}`}>
                          {category.name}
                        </SelectItem>
                      ))
                  )}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />
        <div className="flex items-center space-x-4">
          <FormField
            control={form.control}
            name="vegetarian"
            render={({ field }) => (
              <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4 shadow">
                <FormControl>
                  <Checkbox
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    data-testid="menu-item-vegetarian"
                  />
                </FormControl>
                <div className="space-y-1 leading-none">
                  <FormLabel>Vegetarian</FormLabel>
                </div>
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="spicy"
            render={({ field }) => (
              <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4 shadow">
                <FormControl>
                  <Checkbox
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    data-testid="menu-item-spicy"
                  />
                </FormControl>
                <div className="space-y-1 leading-none">
                  <FormLabel>Spicy</FormLabel>
                </div>
              </FormItem>
            )}
          />
        </div>
        <Button type="submit" disabled={isSubmitting} data-testid="menu-item-submit">
          {isSubmitting ? 'Saving...' : initialData ? 'Update Item' : 'Create Item'}
        </Button>
      </form>
    </Form>
  );
}

